#!/usr/bin/env python3
"""Independent finite arithmetic tests of the proposed mixed-product theorem.
This is not a proof for unbounded parameters. Requires only Python 3.
"""

def check(m):
    assert m >= 2
    base = list(range(m, 2*m))
    # The ideal product generated by the products of the *additive* generating sets.
    generators = sorted({a*b for a in (2, 3) for b in base})
    even_flag = m%2 == 0
    k0 = m + int(even_flag)
    u = 3*k0
    T = u + 2*m
    limit = T + 6*m
    actual = bytearray(limit+1)
    actual[0] = 1
    for n in range(1, limit+1):
        actual[n] = any(n >= a and actual[n-a] for a in generators)
    def predicted(n):
        return n == 0 or (n%2 == 0 and n >= 2*m) or (n%2 == 1 and (n >= T or (n >= u and (n-u)%6 == 0)))
    for n in range(limit+1):
        assert actual[n] == predicted(n), (m,n,"membership")
    gaps = [n for n in range(1,T) if not actual[n]]
    F = max(gaps)
    g = len(gaps)
    embedding = [n for n in range(1,T+2*m) if actual[n] and not any(actual[j] and actual[n-j] for j in range(1,n))]
    pseudo = [n for n in gaps if all(actual[n+a] for a in generators)]
    F_formula = T - 2 - 2*int(m%3 == 1)
    g_formula = m-1 + (T-1)//2 - (m+2)//3
    generator_formula = [2*m+2*j for j in range(m)] + [u+6*j for j in range((m+2)//3)]
    pf_formula = [6*j for j in range(1,(2*m-1)//6+1)] + [u+2*j for j in range(m) if j%3 != 0] + ([u-2] if m%3==1 else [])
    assert F == F_formula, (m,F,F_formula)
    assert g == g_formula, (m,g,g_formula)
    assert embedding == sorted(generator_formula), (m,embedding,generator_formula)
    assert pseudo == sorted(pf_formula), (m,pseudo,pf_formula)
    return F,g,len(embedding),len(pseudo)

if __name__ == '__main__':
    for m in range(2,161):
        check(m)
    for m in range(2,15):
        print(f'm={m:2d}: Frobenius={check(m)[0]:3d}, genus={check(m)[1]:3d}, edim={check(m)[2]:3d}, type={check(m)[3]:3d}')
    print('VERIFY_OK m=2..160 exact DP multiplication, full normal form, Frobenius, genus, minimal generators, pseudo-Frobenius')
